-- H2-03 Pharma OA inventory and order persistence. Normal uninstall policy: retain.
CREATE TABLE IF NOT EXISTS pharma_oa_stock_batches (id VARCHAR(64) PRIMARY KEY, product_id VARCHAR(64) NOT NULL, batch_no VARCHAR(128) NOT NULL, production_date DATETIME(3) NOT NULL, expires_at DATETIME(3) NOT NULL, created_at DATETIME(3) NOT NULL, updated_at DATETIME(3) NOT NULL, created_by VARCHAR(64) NOT NULL DEFAULT '', updated_by VARCHAR(64) NOT NULL DEFAULT '', UNIQUE KEY uk_pharma_batches_product_no(product_id,batch_no), KEY idx_pharma_batches_expiry(expires_at,product_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS pharma_oa_stock_balances (id VARCHAR(64) PRIMARY KEY, product_id VARCHAR(64) NOT NULL, warehouse_id VARCHAR(64) NOT NULL, area_id VARCHAR(64) NOT NULL, location_id VARCHAR(64) NOT NULL, batch_id VARCHAR(64) NOT NULL, quantity INT NOT NULL, locked_quantity INT NOT NULL, version BIGINT NOT NULL DEFAULT 1, created_at DATETIME(3) NOT NULL, updated_at DATETIME(3) NOT NULL, created_by VARCHAR(64) NOT NULL DEFAULT '', updated_by VARCHAR(64) NOT NULL DEFAULT '', UNIQUE KEY uk_pharma_balance_position(product_id,warehouse_id,area_id,location_id,batch_id), KEY idx_pharma_balance_warehouse_product(warehouse_id,product_id), KEY idx_pharma_balance_batch(batch_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS pharma_oa_stock_ledger (id VARCHAR(64) PRIMARY KEY, operation VARCHAR(32) NOT NULL, reference_id VARCHAR(128) NOT NULL, product_id VARCHAR(64) NOT NULL, warehouse_id VARCHAR(64) NOT NULL, area_id VARCHAR(64) NOT NULL, location_id VARCHAR(64) NOT NULL, batch_id VARCHAR(64) NOT NULL, quantity_delta INT NOT NULL, balance_after INT NOT NULL, occurred_at DATETIME(3) NOT NULL, idempotency_key VARCHAR(255) NOT NULL, created_at DATETIME(3) NOT NULL, created_by VARCHAR(64) NOT NULL DEFAULT '', UNIQUE KEY uk_pharma_ledger_idempotency(idempotency_key), KEY idx_pharma_ledger_reference_time(reference_id,occurred_at), KEY idx_pharma_ledger_position_time(product_id,warehouse_id,batch_id,occurred_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS pharma_oa_stock_locks (id VARCHAR(64) PRIMARY KEY, balance_id VARCHAR(64) NOT NULL, quantity INT NOT NULL, reason VARCHAR(512) NOT NULL DEFAULT '', status VARCHAR(32) NOT NULL, released_at DATETIME(3) NULL, created_at DATETIME(3) NOT NULL, updated_at DATETIME(3) NOT NULL, created_by VARCHAR(64) NOT NULL DEFAULT '', updated_by VARCHAR(64) NOT NULL DEFAULT '', KEY idx_pharma_locks_balance_status(balance_id,status)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS pharma_oa_purchase_requests (id VARCHAR(64) PRIMARY KEY, number VARCHAR(128) NOT NULL, supplier_id VARCHAR(64) NOT NULL, requester_id VARCHAR(64) NOT NULL, approver_id VARCHAR(64) NOT NULL, reason VARCHAR(1024) NOT NULL DEFAULT '', lines_json LONGTEXT NOT NULL, total_amount DECIMAL(18,2) NOT NULL, status VARCHAR(32) NOT NULL, workflow_instance_id VARCHAR(64) NOT NULL, purchase_order_id VARCHAR(64) NOT NULL DEFAULT '', created_at DATETIME(3) NOT NULL, updated_at DATETIME(3) NOT NULL, created_by VARCHAR(64) NOT NULL DEFAULT '', updated_by VARCHAR(64) NOT NULL DEFAULT '', UNIQUE KEY uk_pharma_purchase_requests_number(number), KEY idx_pharma_purchase_requests_status_approver(status,approver_id), KEY idx_pharma_purchase_requests_supplier(supplier_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS pharma_oa_purchase_orders (id VARCHAR(64) PRIMARY KEY, number VARCHAR(128) NOT NULL, purchase_request_id VARCHAR(64) NOT NULL, supplier_id VARCHAR(64) NOT NULL, lines_json LONGTEXT NOT NULL, total_amount DECIMAL(18,2) NOT NULL, status VARCHAR(32) NOT NULL, approved_by VARCHAR(64) NOT NULL, approved_at DATETIME(3) NOT NULL, created_at DATETIME(3) NOT NULL, updated_at DATETIME(3) NOT NULL, created_by VARCHAR(64) NOT NULL DEFAULT '', updated_by VARCHAR(64) NOT NULL DEFAULT '', UNIQUE KEY uk_pharma_purchase_orders_number(number), UNIQUE KEY uk_pharma_purchase_orders_request(purchase_request_id), KEY idx_pharma_purchase_orders_supplier_status(supplier_id,status)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS pharma_oa_purchase_inbounds (id VARCHAR(64) PRIMARY KEY, number VARCHAR(128) NOT NULL, purchase_order_id VARCHAR(64) NOT NULL, warehouse_id VARCHAR(64) NOT NULL, area_id VARCHAR(64) NOT NULL, location_id VARCHAR(64) NOT NULL, lines_json LONGTEXT NOT NULL, status VARCHAR(32) NOT NULL, received_by VARCHAR(64) NOT NULL, received_at DATETIME(3) NOT NULL, attachments_json LONGTEXT NOT NULL, idempotency_key VARCHAR(255) NOT NULL, created_at DATETIME(3) NOT NULL, updated_at DATETIME(3) NOT NULL, created_by VARCHAR(64) NOT NULL DEFAULT '', updated_by VARCHAR(64) NOT NULL DEFAULT '', UNIQUE KEY uk_pharma_inbounds_number(number), UNIQUE KEY uk_pharma_inbounds_idempotency(idempotency_key), KEY idx_pharma_inbounds_order(purchase_order_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS pharma_oa_sales_orders (id VARCHAR(64) PRIMARY KEY, number VARCHAR(128) NOT NULL, customer_id VARCHAR(64) NOT NULL, lines_json LONGTEXT NOT NULL, total_amount DECIMAL(18,2) NOT NULL, status VARCHAR(32) NOT NULL, organization_id VARCHAR(64) NOT NULL DEFAULT '', actor_id VARCHAR(64) NOT NULL DEFAULT '', business_created_at DATETIME(3) NOT NULL, created_at DATETIME(3) NOT NULL, updated_at DATETIME(3) NOT NULL, created_by VARCHAR(64) NOT NULL DEFAULT '', updated_by VARCHAR(64) NOT NULL DEFAULT '', UNIQUE KEY uk_pharma_sales_orders_number(number), KEY idx_pharma_sales_orders_customer_status(customer_id,status), KEY idx_pharma_sales_orders_scope(organization_id,created_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS pharma_oa_sales_outbounds (id VARCHAR(64) PRIMARY KEY, number VARCHAR(128) NOT NULL, sales_order_id VARCHAR(64) NOT NULL, customer_id VARCHAR(64) NOT NULL, warehouse_id VARCHAR(64) NOT NULL, area_id VARCHAR(64) NOT NULL, location_id VARCHAR(64) NOT NULL, lines_json LONGTEXT NOT NULL, status VARCHAR(32) NOT NULL, shipped_by VARCHAR(64) NOT NULL, shipped_at DATETIME(3) NOT NULL, idempotency_key VARCHAR(255) NOT NULL, created_at DATETIME(3) NOT NULL, updated_at DATETIME(3) NOT NULL, created_by VARCHAR(64) NOT NULL DEFAULT '', updated_by VARCHAR(64) NOT NULL DEFAULT '', UNIQUE KEY uk_pharma_outbounds_number(number), UNIQUE KEY uk_pharma_outbounds_idempotency(idempotency_key), KEY idx_pharma_outbounds_order(sales_order_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS pharma_oa_stocktakes (id VARCHAR(64) PRIMARY KEY, number VARCHAR(128) NOT NULL, product_id VARCHAR(64) NOT NULL, warehouse_id VARCHAR(64) NOT NULL, area_id VARCHAR(64) NOT NULL, location_id VARCHAR(64) NOT NULL, batch_id VARCHAR(64) NOT NULL, system_quantity INT NOT NULL, actual_quantity INT NOT NULL, difference INT NOT NULL, reason VARCHAR(1024) NOT NULL DEFAULT '', approver_id VARCHAR(64) NOT NULL, workflow_instance_id VARCHAR(64) NOT NULL, ledger_id VARCHAR(64) NOT NULL DEFAULT '', status VARCHAR(32) NOT NULL, actor_id VARCHAR(64) NOT NULL, approved_by VARCHAR(64) NOT NULL DEFAULT '', business_created_at DATETIME(3) NOT NULL, completed_at DATETIME(3) NULL, created_at DATETIME(3) NOT NULL, updated_at DATETIME(3) NOT NULL, created_by VARCHAR(64) NOT NULL DEFAULT '', updated_by VARCHAR(64) NOT NULL DEFAULT '', UNIQUE KEY uk_pharma_stocktakes_number(number), KEY idx_pharma_stocktakes_warehouse_status(warehouse_id,status)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS pharma_oa_transfers (id VARCHAR(64) PRIMARY KEY, number VARCHAR(128) NOT NULL, product_id VARCHAR(64) NOT NULL, batch_id VARCHAR(64) NOT NULL, quantity INT NOT NULL, source_warehouse_id VARCHAR(64) NOT NULL, source_area_id VARCHAR(64) NOT NULL, source_location_id VARCHAR(64) NOT NULL, target_warehouse_id VARCHAR(64) NOT NULL, target_area_id VARCHAR(64) NOT NULL, target_location_id VARCHAR(64) NOT NULL, out_ledger_id VARCHAR(64) NOT NULL, in_ledger_id VARCHAR(64) NOT NULL, status VARCHAR(32) NOT NULL, transferred_by VARCHAR(64) NOT NULL, transferred_at DATETIME(3) NOT NULL, idempotency_key VARCHAR(255) NOT NULL, created_at DATETIME(3) NOT NULL, updated_at DATETIME(3) NOT NULL, created_by VARCHAR(64) NOT NULL DEFAULT '', updated_by VARCHAR(64) NOT NULL DEFAULT '', UNIQUE KEY uk_pharma_transfers_number(number), UNIQUE KEY uk_pharma_transfers_idempotency(idempotency_key), KEY idx_pharma_transfers_status(status)) ENGINE=InnoDB;
